    input [3:0] ABCD,
    input clk,              // Added clk as an input
    output reg [15:0] out
);reg [15:0] stage1_out;
reg [15:0] stage2_out;

always @ (posedge clk) begin
    stage1_out <= {~ABCD[0], ~ABCD[1], ~ABCD[2], ~ABCD[3]};
end

always @ (posedge clk) begin
    stage2_out <= {stage1_out[0], stage1_out[1], stage1_out[2], stage1_out[3], 
