  input   [31:0] i_data0;
  output  [31:0]
    o_data0;

  //Multipliers:
  wire [31:0]
    w1,
    w16,
    w17,
    w4,
    w13,
    w6656,
    w6643,
    w16384,
    w23027;

  assign w1 = i_data0;
  assign w4 = w1 << 2; // missing multiplier
  assign w16 = w1 << 4;
