  reg latch_out;

  always @ (posedge gated_clk or posedge TE) begin
    if (TE)
      latch_out <= 1'b0; // Reset or disable.
    else if (EN)
      latch_out <= 1'b1; // Enable latch
  end

  assign ENCLK = latch_out;

endmodule

