description:
Design a next program counter (NPC) module that generates the next instruction address based on multiple selection criteria. The module takes a 32-bit immediate value, a 3-bit selector input (nPC_sel), a zero flag indicating the result of a comparison, the current program counter (PC), a jump address, and a data bus input (BusA). Depending on the value of nPC_sel and the Zero flag, the module computes NPC by either branching to a target address, incrementing the current PC, or passing through a jump address or BusA. This functionality allows for conditional and unconditional control flow in a processor architecture, supporting various branching and jumping operations.
module top_module(
    Imm, nPC_sel, Zero, PC, JumpAddr, BusA,
    NPC
);

code:
module top_module(
    Imm, nPC_sel, Zero, PC, JumpAddr, BusA,
    NPC
);input [31:0] Imm;
    input [2:0] nPC_sel;
    input Zero;
    input [31:0] PC, BusA;
    input [25:0] JumpAddr;
    output reg [31:0] NPC; 

always @(*) begin
    if (nPC_sel == 3'b001 && Zero == 1)

        NPC = PC + 1 + Imm;
    else if (nPC_sel == 3'b010 && Zero == 0)
        NPC = PC + 1 + Imm;
    else if (nPC_sel == 3'b011) 
        NPC = JumpAddr;
    else if (nPC_sel == 3'b100) 
        NPC = JumpAddr;
    else if (nPC_sel == 3'b101) 
        NPC = BusA;
    else if (nPC_sel == 3'b110)
        NPC = PC;
    else
        NPC = PC + 1;
end

endmodule

